var payload = msg.payload; 

// Temperatura
var temperatura = payload.Temperatura;
// Potenciômetro
var umidade = payload.Potenciometro;

// Pegando o valor do slider de temperatura mínima e máxima
var tempMinima = flow.get('tempMinima') || 10;  // Valor padrão de 10 se o slider não estiver configurado
var tempMaxima = flow.get('tempMaxima') || 30;  // Valor padrão de 30 se o slider não estiver configurado
// Pegando o valor do slider de umidade mínima e máxima
var umidadeMinima = flow.get('umidadeMinima') || 20;  // Valor padrão de 20 se o slider não estiver configurado
var umidadeMaxima = flow.get('umidadeMaxima') || 80;  // Valor padrão de 80 se o slider não estiver configurado


// Verificação da Temperatura
if (temperatura < tempMinima) {
    msg.payload = "Low Temperature";
    return msg;
} else if (temperatura > tempMaxima) {
    msg.payload = "High Temperature";
    return msg;
}

// Verificação da Umidade
if (umidade < 20) {
    msg.payload = "Low Humidity!";
    return msg;
} else if (umidade > 80) {
    msg.payload = "High Humidity";
    return msg;
}

// Extrai o userId do tópico: sensorVerde/user_321
const topicParts = msg.topic.split("/");
const userId = topicParts[1];

if (!userId) return null;

// Recupera cache existente
let sensores = flow.get("sensores") || {};

// Inicializa se não existir
if (!sensores[userId]) {
    sensores[userId] = {};
}

// Mescla os dados recebidos
Object.assign(sensores[userId], msg.payload);

// Salva novamente no contexto
flow.set("sensores", sensores);

// Envia somente os dados desse usuário para o dashboard
msg.payload = sensores[userId];
msg.payload.userId = userId;

return msg;

var accounts = global.get("accounts") || [
    { username: "guest", password: "guest", esp32: "user_123" },
    { username: "guest1", password: "guest1", esp32: "user_321" }
];

// Se accounts não for um array, transforme em array
if (!Array.isArray(accounts)) {
    accounts = Object.values(accounts);
}

var username = msg.payload.username;
var password = msg.payload.password;

// Obtém o Socket ID do cliente atual
var socketId = msg._client?.socketId;

// Inicializa a mensagem de retorno
msg.topic = "login_failed";
msg.payload = "Usuário Não Encontrado!";

// Verifica se o usuário existe e se a senha está correta
accounts.forEach(function (account) {
    if (account.username === username) {
        msg.topic = "login_failed";
        msg.payload = "Senha Incorreta!";

        if (account.password === password) {
            msg.topic = "login_success";
            msg.payload = {
                username: username,
                initials: username.charAt(0).toUpperCase(),
                socketId: socketId
            };

            // Armazena o estado de login no flow context, usando o Socket ID como chave
            var loggedInUsers = global.get("loggedInUsers") || {};
            loggedInUsers[socketId] = {
                username: username,
                esp32: account.esp32,
                socketId: socketId
            };

            global.set("loggedInUsers", loggedInUsers);
        }
    }
});

return msg;

// Obtém o Socket ID do cliente atual
var socketId = msg._client?.socketId;

// Remove o usuário logado do flow context
var loggedInUsers = global.get("loggedInUsers") || {};
delete loggedInUsers[socketId];
global.set("loggedInUsers", loggedInUsers);

// Retorna uma mensagem de logout
msg.topic = "logout_success";
msg.payload = "Logout realizado com sucesso!"; // Mensagem de sucesso
msg.user = {
    username: "", // Nome do usuário vazio
    initials: ""  // Iniciais vazias
};
return msg;

var loggedInUser = flow.get("loggedInUser") || null;
msg.payload = loggedInUser;
return msg;

// Recupera a variável global account
let account = global.get('accounts') || {};

// Acessa os dados do payload
let users = msg.payload;

// Função para atualizar ou adicionar usuários
for (let userKey in users) {
    let user = users[userKey];

    // Verifica se o usuário já existe
    if (account[userKey]) {
        // Se o usuário já existir, atualiza as informações
        account[userKey].username = user.username;
        account[userKey].password = user.password;
        account[userKey].esp32 = user.esp32;
    } else {
        // Caso não exista, adiciona um novo usuário
        account[userKey] = {
            username: user.username,
            password: user.password,
            esp32: user.esp32
        };
    }
}

// Função para remover usuários que não estão mais no payload
for (let userKey in account) {
    if (!users[userKey]) {
        // Se o usuário não estiver em users, remove de account
        delete account[userKey];
    }
}

// Atualiza a variável global com os dados atualizados
global.set('accounts', account);

// Retorna a saída como o payload atualizado
msg.payload = account;
return msg;

// ========================================
// 3. FUNÇÃO: Gerar Dados (Dropdown de Datas)
// ========================================

var socketId = msg._client?.socketId;
var loggedInUsers = global.get("loggedInUsers") || {};

if (!socketId) {
    for (var key in loggedInUsers) {
        if (loggedInUsers[key].socketId) {
            socketId = loggedInUsers[key].socketId;
            break;
        }
    }
}

if (!socketId || !loggedInUsers[socketId]) {
    return null;
}

var espNumber = loggedInUsers[socketId].esp32;

// Últimos 7 dias
var options = [];
for (var i = 0; i < 7; i++) {
    var date = new Date();
    date.setDate(date.getDate() - i);

    var day = String(date.getDate()).padStart(2, '0');
    var month = String(date.getMonth() + 1).padStart(2, '0');
    var year = date.getFullYear();

    var dateString = `${day}-${month}-${year}`;

    options.push({
        label: dateString,
        value: dateString
    });
}

msg.options = options;
msg.espNumber = espNumber;

return msg;

// ========================================
// 4. FUNÇÃO: Armazenar Data Selecionada
// ========================================

var selectedDate = msg.payload;
flow.set("selectedDate", selectedDate);

var socketId = msg._client?.socketId;
var loggedInUsers = global.get("loggedInUsers") || {};

if (socketId && loggedInUsers[socketId]) {
    msg.espNumber = loggedInUsers[socketId].esp32;
    msg.selectedDate = selectedDate;
    return msg;
}

return null;

// ========================================
// 5. FUNÇÃO: Caminho Firestore (READ)
// ========================================

var espNumber = msg.espNumber;
var selectedDate = msg.selectedDate || msg.payload;

if (!espNumber || !selectedDate) {
    return null;
}

msg.firestore = {
    collection: `sensorData/${espNumber}/${selectedDate}`,
    query: [
        { orderBy: ["Timestamp", "asc"] }
    ]
};

node.log("Buscando em: " + msg.firestore.collection);

return msg;

// ========================================
// 6. FUNÇÃO: Processar Dados (ROBUSTO)
// ========================================

let docs = msg.payload;

// Caso Firestore retorne ARRAY (padrão)
if (Array.isArray(docs)) {
    docs = docs.reduce((acc, d) => {
        acc[d.Timestamp] = d;
        return acc;
    }, {});
}

// Agora garantimos que é objeto
if (docs && typeof docs === "object" && Object.keys(docs).length > 0) {

    let sortedDocs = Object.values(docs)
        .filter(d => d.Timestamp !== undefined)
        .sort((a, b) => a.Timestamp - b.Timestamp);

    let last = sortedDocs[sortedDocs.length - 1];

    let historicoTemperatura = sortedDocs.map(doc => ({
        x: doc.Timestamp,
        y: doc.Temperatura
    }));

    let historicoPotenciometro = sortedDocs.map(doc => ({
        x: doc.Timestamp,
        y: doc.Potenciometro
    }));

    msg.payload = {
        temperatura: last.Temperatura,
        potenciometro: last.Potenciometro,
        historicoTemperatura: {
            series: ["Temperatura"],
            data: [historicoTemperatura],
            labels: [""]
        },
        historicoPotenciometro: {
            series: ["Potenciômetro"],
            data: [historicoPotenciometro],
            labels: [""]
        }
    };

    return msg;
}

return null;

var payload = msg.payload;
var topic = msg.topic;

// Só continua se for leitura de sensor válida
if (
    payload.Potenciometro === undefined ||
    payload.Temperatura === undefined
) {
    node.warn("Mensagem ignorada (não é leitura de sensor)");
    return null; // ⛔ interrompe o flow
}

// ID do usuário
var espNumber = topic.split("/")[1];

// Timestamp
var timestamp = Date.now();

// Data DD-MM-YYYY
var date = new Date();
var day = String(date.getDate()).padStart(2, '0');
var month = String(date.getMonth() + 1).padStart(2, '0');
var year = date.getFullYear();
var dateString = `${day}-${month}-${year}`;

// Firestore path
msg.firestore = {
    operation: "set",
    collection: `sensorData/${espNumber}/${dateString}`,
    document: String(timestamp)
};

// Payload correto
msg.payload = {
    Potenciometro: payload.Potenciometro,
    Temperatura: payload.Temperatura,
    Timestamp: timestamp
};

return msg;
